:root {
  --bg-0: #0c0d0f;
  --bg-1: #12141a;
  --bg-2: #181b22;
  --bg-3: #1e222b;
  --ink: #f4f1ec;
  --ink-soft: #c8c4bc;
  --muted: #8b8680;
  --line: rgba(244, 241, 236, 0.08);
  --line-strong: rgba(244, 241, 236, 0.14);
  --rosso: #d40000;
  --rosso-deep: #8a0000;
  --gold: #c9a227;
  --ok: #3d9a6a;
  --warn: #c47a3a;
  --danger: #c44a3a;
  --radius: 4px;
  --radius-lg: 10px;
  --font-display: "Archivo Narrow", "Archivo", sans-serif;
  --font-ui: "Archivo", sans-serif;
  --font-mono: "JetBrains Mono", monospace;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --pad: 1.25rem;
}

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; }
body {
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.45;
  background:
    linear-gradient(105deg, rgba(212, 0, 0, 0.07) 0%, transparent 38%),
    linear-gradient(180deg, #14161c 0%, var(--bg-0) 42%, #0a0b0e 100%);
  background-attachment: fixed;
}

.noise {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: 0;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

.topbar, .layout { position: relative; z-index: 1; }

/* ——— Header ——— */
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem var(--pad);
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(18, 20, 26, 0.92), rgba(12, 13, 15, 0.75));
  backdrop-filter: blur(10px);
  animation: rise 0.7s var(--ease) both;
}
.brand { display: flex; align-items: center; gap: 1rem; min-width: 0; }
.brand-mark {
  width: 5px;
  height: 44px;
  flex-shrink: 0;
  background: linear-gradient(180deg, var(--rosso) 0%, var(--rosso-deep) 100%);
}
.brand h1 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.55rem, 2.4vw, 2rem);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1;
}
.brand p {
  margin: 0.35rem 0 0;
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.top-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  justify-content: flex-end;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  padding: 0.32rem 0.65rem;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.02);
}
.status::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 1px;
  background: var(--muted);
}
.status.offline { color: #e8a090; border-color: rgba(196, 74, 58, 0.35); }
.status.offline::before { background: var(--danger); }
.status.online { color: #9ed4b5; border-color: rgba(61, 154, 106, 0.4); }
.status.online::before { background: var(--ok); }
.status.sync { color: #e4d4a0; border-color: rgba(201, 162, 39, 0.35); }
.status.sync::before { background: var(--gold); }
.event {
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  max-width: 220px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ——— Layout ——— */
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 1fr);
  gap: 1rem;
  padding: 1rem var(--pad) 1.5rem;
  min-height: calc(100vh - 78px);
  animation: rise 0.85s var(--ease) 0.08s both;
}

.stage {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(ellipse 80% 50% at 30% 40%, rgba(212, 0, 0, 0.08), transparent 60%),
    linear-gradient(165deg, #1a1d24, #0e1014 70%);
  display: flex;
  flex-direction: column;
  min-height: 540px;
}
.stage-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--line);
}
.stage-head h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.95rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 600;
}
.stage-head span {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  color: var(--muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.stage-grid {
  flex: 1;
  min-height: 0;
  background: transparent;
}
#ferrari-svg { width: 100%; height: 100%; display: block; min-height: 480px; }
.room-label {
  fill: #6a7076;
  font-size: 11px;
  font-family: var(--font-mono);
  letter-spacing: 0.18em;
}
.tiny { fill: #7a756e; font-size: 10px; font-family: var(--font-mono); }

/* Butterfly doors + actuators */
.door-panel {
  transform-origin: 8px 50px;
  transition: transform 0.95s cubic-bezier(0.34, 1.3, 0.64, 1);
}
.door-panel.open {
  transform: rotate(-68deg) translate(-12px, -42px);
}
.door-panel.passenger {
  transform-origin: 10px 40px;
}
.door-panel.passenger.open {
  transform: rotate(64deg) translate(18px, -48px);
}
.roof-panel {
  transform-origin: 520px 170px;
  transition: transform 0.9s var(--ease), opacity 0.55s;
}
.roof-panel.open {
  transform: translateY(-48px) rotate(-8deg) scale(0.9);
  opacity: 0.2;
}
.spoiler {
  transform: translate(730px, 258px) scaleY(0.85);
  transition: transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
  opacity: 0.85;
}
.spoiler.out {
  transform: translate(730px, 205px) scaleY(1);
}
.spoiler.out .spoiler-tag { opacity: 1; }
.wheel .rim-spokes {
